-- Displaying the dataset

select *
from `customer_behavior_analysis.customer_behavior`
 LIMIT 5;

 --1. Total revenue generated by male vs female customers

 select gender, sum(purchase_amount) as total_revenue
 from `customer_behavior_analysis.customer_behavior`
 group by gender
 order by total_revenue desc;

--2. Customer who used a discount but still spent more than the average purchase amount

select customer_id, purchase_amount
from `customer_behavior_analysis.customer_behavior`
where discount_applied = true  and  purchase_amount >= (select avg(purchase_amount)
from `customer_behavior_analysis.customer_behavior` );

--3. The top 5 five products with the highest average review rating 

select item_purchased, round(avg(review_rating) ,2)as avg_review_rating
from `customer_behavior_analysis.customer_behavior`
group by item_purchased
order by avg_review_rating desc
limit 5;

--4. Comparing the average purchase amounts betwteen standard and express shipping 

select shipping_type, round(avg(purchase_amount) ,2)as avg_purchase_amount
from `customer_behavior_analysis.customer_behavior`
where shipping_type in ('Standard','Express')
group by shipping_type
order by avg_purchase_amount;

--5. Comparing the average spend and total revenue between subscribers and non subscribers

select subscription_status,count(customer_id) as total_customer, round(avg(purchase_amount),2) as avg_spend, sum(purchase_amount) as total_revenue
from `customer_behavior_analysis.customer_behavior`
group by subscription_status
order by avg_spend;

--6. The 5 products with the highest percentage of purchases with discount applied

select item_purchased, round(100* sum(case when discount_applied= true  then 1 else 0 end )/count(*), 2) as discount_rate
from `customer_behavior_analysis.customer_behavior`
group by item_purchased
order by discount_rate desc
limit 5 ;

--7. Segmenting customer based on their number of previous purchase and showing the count fro each segment

with segmentation as( 
select customer_id ,  
case 
when previous_purchases = 1 then "New customer" 
when previous_purchases between 2 and 10 then "Returning customer"
else "loyal customer"
end as status
from `customer_behavior_analysis.customer_behavior`
 )
select status, count(customer_id) as total_customers
from segmentation
group by status
order by total_customers;

--8. Top 3 most purchased product within each category

with item_count as
(
  select 
  category, 
  item_purchased, 
  count(customer_id) as total_orders,
   row_number()over
   ( partition by category order by count(customer_id)desc
   ) as item_rank
  from `customer_behavior_analysis.customer_behavior`
  group by category, item_purchased
)
select item_rank, category, item_purchased,total_orders
from item_count
where item_rank <= 3;

--9. Are customer who are repeat buyers( more than 5 previous purchases) also likely to be subscribers

select subscription_status, count(customer_id)as buyers
from `customer_behavior_analysis.customer_behavior`
where previous_purchases > 5 
group by subscription_status;

--10. The revenue by age group

select age_group, sum(purchase_amount)as revenue
from `customer_behavior_analysis.customer_behavior`
group by age_group
order by revenue desc;
